// Gather the queued rows (HTTP node may emit one item per row OR a single
// item whose json is the whole array) and build ONE BatchData skip-trace body
// of up to 100 propertyAddress objects. Keep `rows` so results map back by id.
const items = $input.all();
let rows = [];
if (items.length === 1 && Array.isArray(items[0].json)) rows = items[0].json;
else rows = items.map(i => i.json);
rows = rows.filter(r => r && r.id && r.street);
if (rows.length === 0) { return [{ json: { count: 0, requests: [], rows: [] } }]; }
const requests = rows.map(r => {
  const pa = { street: String(r.street || '').trim(), city: String(r.city || '').trim(), state: String(r.state || 'RI').trim() };
  if (r.zip) pa.zip = String(r.zip).trim();
  return { propertyAddress: pa };
});
return [{ json: { count: rows.length, requests, rows } }];

// Map BatchData persons back to the queued rows by normalized property address,
// then emit one PATCH-ready item per row. Defensive about field names — if the
// live response differs, adjust pickPhone/pickEmail/pickName below (the verified
// shape is documented in 401_batchdata_connection.md: results.persons[]).
const resp = $input.first().json || {};
const rows = ($('Build BatchData Request').first().json.rows) || [];
const persons = (resp.results && resp.results.persons) || resp.persons || [];
const norm = s => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]/g, '');
function paOf(p) { return p.propertyAddress || p.property || p.address || {}; }
function keyOf(street, city) { return norm(street) + '|' + norm(city); }
const byProp = {};
for (const p of persons) { const a = paOf(p); const k = keyOf(a.street, a.city || a.cityName); (byProp[k] = byProp[k] || []).push(p); }
function pickPhones(p) { const arr = p.phoneNumbers || p.phones || p.phoneNumber || []; return (Array.isArray(arr) ? arr : [arr]).map(x => (x && (x.number || x.phone || x.phoneNumber)) || (typeof x === 'string' ? x : null)).filter(Boolean); }
function pickEmails(p) { const arr = p.emails || p.emailAddresses || p.email || []; return (Array.isArray(arr) ? arr : [arr]).map(x => (x && (x.email || x.address)) || (typeof x === 'string' ? x : null)).filter(Boolean); }
function pickName(p) { const n = p.name || {}; return n.full || [n.first, n.last].filter(Boolean).join(' ') || p.fullName || [p.firstName, p.lastName].filter(Boolean).join(' ') || null; }
function pickMailing(p) { return p.mailingAddress || p.mailing || {}; }
const nowIso = new Date().toISOString();
return rows.map(r => {
  const matches = byProp[keyOf(r.street, r.city)] || [];
  const person = matches[0];
  if (!person) { return { json: { id: r.id, status: 'no_match', skiptraced_at: nowIso } }; }
  const phones = pickPhones(person); const emails = pickEmails(person); const m = pickMailing(person); const pa = paOf(person);
  return { json: {
    id: r.id, status: 'traced', skiptraced_at: nowIso,
    owner_name: pickName(person),
    owner_phone: phones[0] || null,
    owner_phone2: phones[1] || null,
    owner_email: emails[0] || null,
    owner_mailing_street: m.street || null,
    owner_mailing_city: m.city || null,
    owner_mailing_state: m.state || null,
    owner_mailing_zip: m.zip || m.postalCode || null,
    address_validity: pa.addressValidity || pa.validity || null,
    skiptrace_raw: person
  } };
});
